pts/setup.mjs\",\n    \"bundle:status\": \"node ./bin/rea-shim.mjs --shim-status\",\n    \"bundle:dry-run\": \"node ./scripts/setup.mjs --reuse --dry-run\",\n    \"bundle:audit\": \"node ./scripts/audit-manifest.mjs\",\n    \"bundle:deps\": \"node ./scripts/check-dependency-advisories.mjs\",\n    \"bundle:test\": \"node --test ./scripts/setup.test.mjs ./scripts/deps.test.mjs ./scripts/host-compat.test.mjs ./scripts/hardening.test.mjs\",\n    \"bundle:host-compat\": \"node ./scripts/host-compat.mjs\"\n  },\n  \"engines\": {\n    \"node\": \"^22.23.4 || ^24.22.1 || >=26.12.1\",\n    \"dsh\": \">=0.1.7-rc.2 <0.3.0-0\"\n  },\n  \"publishConfig\": {\n    \"registry\": \"https://registry.npmjs.org/\"\n  }\n}\n"
